DROP TABLE IF EXISTS `client_payment_type`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `client_payment_type` (
  `id` int NOT NULL AUTO_INCREMENT,
  `client_id` int unsigned DEFAULT NULL COMMENT 'Client',
  `is_cash` int DEFAULT NULL COMMENT 'Cash payment',
  `is_terminal` int DEFAULT NULL COMMENT 'Terminal payment',
  `is_pod` int DEFAULT NULL COMMENT 'Payin payment',
  `is_inmagpay` int DEFAULT NULL COMMENT 'Internet magazine payment',
  `is_contract` int DEFAULT NULL COMMENT 'Contract payment',
  PRIMARY KEY (`id`),
  KEY `idx-client_payment_type-client_id` (`client_id`)
