--
-- Table structure for table `clients`
--

DROP TABLE IF EXISTS `clients`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `clients` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL COMMENT 'Name',
  `nick_name` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `loyalty_card` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `region_id` int NOT NULL COMMENT 'Region Id',
  `city_id` int NOT NULL COMMENT 'City Id',
  `address` text CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci COMMENT 'Address',
  `phone_number` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `contact_number` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `contact_name` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `other_number` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci DEFAULT NULL COMMENT 'Other Number',
  `inn` int NOT NULL COMMENT 'INN',
  `okpo` int DEFAULT NULL COMMENT 'OKPO',
  `oked` int DEFAULT NULL COMMENT 'OKED',
  `okonx` int DEFAULT NULL COMMENT 'OKONX',
  `soogu` int DEFAULT NULL COMMENT 'SOOGU',
  `bank_name` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci DEFAULT NULL COMMENT 'Bank Name',
  `bank_account` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `mfo` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `director_fullname` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci DEFAULT NULL COMMENT 'Director Fullname',
  `contract_id` int DEFAULT NULL COMMENT 'Contract',
  `plan_id` int DEFAULT NULL COMMENT 'Plan',
  `created_at` int DEFAULT NULL,
  `updated_at` int DEFAULT NULL,
  `is_online_store` int DEFAULT NULL,
  `in_warehouse` int DEFAULT '0',
  `is_nds` tinyint(1) DEFAULT NULL,
  `is_own_price` smallint DEFAULT '0' COMMENT 'Have own price',
  `main_accountant` varchar(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci DEFAULT NULL,
