  `created_at` timestamp NOT NULL DEFAULT '2019-11-04 06:03:42',
  `updated_at` timestamp NOT NULL DEFAULT '2019-11-04 06:03:42',
  `gender` tinyint DEFAULT NULL,
  `discount` decimal(20,2) DEFAULT NULL,
  `is_aktiv` int DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=551210 DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_unicode_ci;
