DROP TABLE IF EXISTS `sign`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sign` (
  `id` int NOT NULL AUTO_INCREMENT,
  `user_id` int DEFAULT NULL COMMENT 'User',
  `waybill_id` int DEFAULT NULL COMMENT 'Waybill',
  `barcode` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `barcodes` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `wids` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Waybill list',
  `full_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Full name',
  `latitude` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Latitude',
  `longitude` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Longitude',
  `is_delivery` int DEFAULT '1' COMMENT 'Longitude',
  `datetime` int DEFAULT NULL COMMENT 'Date time',
  `created_at` int unsigned DEFAULT NULL COMMENT 'Created at',
  `updated_at` int unsigned DEFAULT NULL COMMENT 'Updated at',
  PRIMARY KEY (`id`),
  KEY `ix_sign_barcode` (`barcode`),
  KEY `ix_sign_barcodes` (`barcodes`)
) ENGINE=InnoDB AUTO_INCREMENT=63652 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

