DROP TABLE IF EXISTS `st_waybill`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `st_waybill` (
  `id` int NOT NULL AUTO_INCREMENT,
  `user_id` int unsigned DEFAULT NULL COMMENT 'User',
  `tracking_number` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci DEFAULT NULL COMMENT 'Tracking number',
  `first_name` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci DEFAULT NULL COMMENT 'First name',
  `last_name` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci DEFAULT NULL COMMENT 'Last name',
  `weight` decimal(20,2) DEFAULT NULL COMMENT 'Weight',
  `is_liquid` tinyint unsigned DEFAULT NULL COMMENT 'Liquid',
  `is_magnetic` tinyint unsigned DEFAULT NULL COMMENT 'Magnetic',
  `is_breakable` tinyint unsigned DEFAULT NULL COMMENT 'Breakable',
  `is_electronic` tinyint unsigned DEFAULT NULL COMMENT 'Electronic',
  `price` decimal(20,2) DEFAULT NULL COMMENT 'Price',
  `currency_code` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci DEFAULT NULL COMMENT 'Currency code',
  `total_price` decimal(20,2) DEFAULT NULL COMMENT 'Total price',
  `shipping_price` decimal(20,2) DEFAULT NULL COMMENT 'Shipping price',
  `address` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci DEFAULT NULL COMMENT 'Address',
  `waybill_id` int DEFAULT NULL COMMENT 'Waybill',
  `package_status` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci DEFAULT NULL COMMENT 'Package status',
  PRIMARY KEY (`id`),
  KEY `idx-st_waybill-tracking_number` (`tracking_number`),
  KEY `idx-st_waybill-waybill_id` (`waybill_id`),
  KEY `idx-st_waybill-package_status` (`package_status`)
) ENGINE=InnoDB AUTO_INCREMENT=20 DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_unicode_ci;
