--
-- Table structure for table `waybill`
--

DROP TABLE IF EXISTS `waybill`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `waybill` (
  `id` int NOT NULL AUTO_INCREMENT,
  `barcode` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Barcode',
  `parent_waybill_id` int unsigned DEFAULT NULL COMMENT 'Parent waybill',
  `shipper_type` smallint DEFAULT NULL COMMENT 'Shipper type',
  `from_branch_id` int unsigned DEFAULT NULL COMMENT 'Shipper branch',
  `from_region_id` int unsigned DEFAULT NULL COMMENT 'Shipper region',
  `from_city_id` int unsigned DEFAULT NULL COMMENT 'Shipper city',
  `from_client_id` int unsigned DEFAULT NULL COMMENT 'Shipper legal client',
  `from_individual_id` int unsigned DEFAULT NULL COMMENT 'Shipper individual',
  `from_latitude` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Shipper latitude',
  `from_longitude` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Shipper longitude',
  `from_layolty_card` int unsigned DEFAULT NULL COMMENT 'Shipper individual layolty card',
  `from_fullname` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Shipper fullname',
  `from_phone_number` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Shipper phone number',
  `from_address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Shipper address',
  `from_comment` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Shipper comment',
  `to_branch_id` int unsigned DEFAULT NULL COMMENT 'Receiver branch',
  `current_branch_id` int DEFAULT NULL,
  `to_region_id` int unsigned DEFAULT NULL COMMENT 'Receiver region',
  `to_city_id` int unsigned DEFAULT NULL COMMENT 'Receiver city',
  `to_client_id` int unsigned DEFAULT NULL COMMENT 'Receiver legal client',
  `to_individual_id` int unsigned DEFAULT NULL COMMENT 'Receiver individual',
  `to_latitude` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Receiver latitude',
  `to_longitude` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Receiver longitude',
  `to_layolty_card` int unsigned DEFAULT NULL COMMENT 'Receiver individual layolty card',
  `to_fullname` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Receiver fullname',
  `to_phone_number` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Receiver phone number',
  `to_address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Receiver address',
  `to_comment` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Receiver comment',
  `transport_type` int DEFAULT '0' COMMENT 'Transport type',
  `plan_id` int DEFAULT NULL COMMENT 'Plan',
  `price_id` int unsigned DEFAULT NULL COMMENT 'Price',
  `weight` decimal(20,2) DEFAULT NULL COMMENT 'Weight',
  `quantity` int unsigned DEFAULT NULL COMMENT 'Quantity',
  `status` int unsigned DEFAULT NULL COMMENT 'Status',
  `is_cancel` int DEFAULT '0',
  `is_return_money` int DEFAULT '0',
  `return_money_amount` decimal(20,2) DEFAULT '0.00',
  `old_status` int DEFAULT NULL COMMENT 'qopga solishda va kuryerga berishda chapdan unga va ungdan chapga utkazilganda saqlanadigan vaqtinchalik status',
  `amount` decimal(20,2) DEFAULT NULL COMMENT 'Amount',
  `discount` decimal(20,2) DEFAULT NULL COMMENT 'Discount',
  `total_price` decimal(20,2) DEFAULT NULL COMMENT 'Total price',
  `payment_type` int DEFAULT NULL COMMENT 'Payment type',
  `is_cash` int DEFAULT '0',
  `cash_amount` decimal(30,2) DEFAULT '0.00',
  `is_contract` smallint DEFAULT NULL COMMENT 'Is contract payment',
  `contract_amount` decimal(30,2) DEFAULT NULL COMMENT 'Contract pay amount',
  `is_inmagpay` smallint DEFAULT '0' COMMENT 'Is internet magazin pay',
  `inmag_amount` decimal(10,0) DEFAULT '0' COMMENT 'Internet magazin pay amount',
  `is_terminal` int DEFAULT '0',
  `terminal_amount` decimal(30,2) DEFAULT '0.00',
  `is_pod` int DEFAULT '0' COMMENT 'Pay on delivery',
  `payin_amount` double DEFAULT NULL COMMENT 'Payin true bugandagi summa',
  `is_cash_payin` int DEFAULT '0',
  `is_terminal_payin` int DEFAULT '0',
  `is_cash_payin_amount` double DEFAULT NULL,
  `is_terminal_payin_amount` double DEFAULT NULL,
  `is_cod` int DEFAULT '0' COMMENT 'is COD',
  `is_delivery` smallint DEFAULT NULL COMMENT 'is Delivery',
  `cod_amount` decimal(30,2) DEFAULT NULL COMMENT 'COD amount',
  `parcel_price` decimal(30,2) DEFAULT '0.00' COMMENT 'Parcel price',
  `cod_type` smallint DEFAULT '0' COMMENT 'COD type',
  `cod_taken` smallint DEFAULT '0' COMMENT 'Is COD taken',
  `cod_take_user` int DEFAULT NULL COMMENT 'COD taken user',
  `cod_percent` smallint DEFAULT NULL COMMENT 'COD percent',
  `cod_percent_amount` decimal(20,2) DEFAULT NULL COMMENT 'COD percent amount',
  `given_money_user` int DEFAULT NULL COMMENT 'Given money user',
  `is_paid` smallint DEFAULT '0',
  `parcel_type` smallint DEFAULT NULL COMMENT 'Parcel type',
  `parcel_list` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Parcel list',
  `return_type` smallint DEFAULT NULL COMMENT 'Revert',
  `formalize_user_id` int unsigned DEFAULT NULL COMMENT 'Formalize user',
  `given_user_id` int unsigned DEFAULT NULL COMMENT 'Given user',
  `pickup_courier_id` int unsigned DEFAULT NULL COMMENT 'Pickup courier',
  `is_pickedup` tinyint(1) DEFAULT NULL,
  `for_sign` int DEFAULT '0',
  `delivery_courier_id` int unsigned DEFAULT NULL COMMENT 'Delivery courier',
  `last_user_id` int unsigned DEFAULT NULL COMMENT 'Last change user',
  `pickup_datetime` int unsigned DEFAULT NULL COMMENT 'Pickup date and time',
  `delivery_datetime` int unsigned DEFAULT NULL COMMENT 'Delivery date and time',
  `bag_datetime` int DEFAULT NULL,
  `to_courier_datetime` int DEFAULT NULL,
  `sended_datetime` int unsigned DEFAULT NULL COMMENT 'Sended date and time',
  `sended_date` date DEFAULT NULL,
  `received_datetime` int unsigned DEFAULT NULL COMMENT 'Received date and time',
  `created_at` int unsigned DEFAULT NULL COMMENT 'Created at',
  `updated_at` int unsigned DEFAULT NULL COMMENT 'Updated at',
  `current_place` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `is_test` int DEFAULT '0',
  `in_warehouse` int DEFAULT NULL,
  `product_id` int DEFAULT NULL,
  `searchable_data` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `accept_ids` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `comments_count` int DEFAULT '0',
  `quantity_numbers` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `current_employee_id` int DEFAULT NULL,
  `package_price` int DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `ix_barcode` (`barcode`),
  KEY `ix_shipper_type` (`shipper_type`),
  KEY `ix_from_branch_id` (`from_branch_id`),
  KEY `ix_from_region_id` (`from_region_id`),
  KEY `ix_from_city_id` (`from_city_id`),
  KEY `ix_from_client_id` (`from_client_id`),
  KEY `ix_from_individual_id` (`from_individual_id`),
  KEY `ix_from_fullname` (`from_fullname`),
  KEY `ix_from_phone_number` (`from_phone_number`),
  KEY `ix_to_branch_id` (`to_branch_id`),
  KEY `ix_to_region_id` (`to_region_id`),
  KEY `ix_to_city_id` (`to_city_id`),
  KEY `ix_to_client_id` (`to_client_id`),
  KEY `ix_to_individual_id` (`to_individual_id`),
  KEY `ix_to_fullname` (`to_fullname`),
  KEY `ix_to_phone_number` (`to_phone_number`),
  KEY `ix_to_address` (`to_address`),
  KEY `ix_status` (`status`),
  KEY `ix_amount` (`amount`),
  KEY `ix_discount` (`discount`),
  KEY `ix_total_price` (`total_price`),
  KEY `ix_payment_type` (`payment_type`),
  KEY `ix_is_cash` (`is_cash`),
  KEY `ix_cash_amount` (`cash_amount`),
  KEY `ix_is_terminal` (`is_terminal`),
  KEY `ix_terminal_amount` (`terminal_amount`),
  KEY `ix_is_pod` (`is_pod`),
  KEY `ix_payin_amount` (`payin_amount`),
  KEY `ix_return_type` (`return_type`),
  KEY `ix_formalize_user_id` (`formalize_user_id`),
  KEY `ix_given_user_id` (`given_user_id`),
  KEY `ix_pickup_courier_id` (`pickup_courier_id`),
  KEY `ix_is_pickedup` (`is_pickedup`),
  KEY `ix_delivery_courier_id` (`delivery_courier_id`),
  KEY `ix_last_user_id` (`last_user_id`),
  KEY `ix_sended_datetime` (`sended_datetime`),
  KEY `ix_sended_date` (`sended_date`),
  KEY `ix_received_datetime` (`received_datetime`),
  KEY `ix_waybill_is_cancel` (`is_cancel`),
  KEY `ix_waybill_is_return_money` (`is_return_money`),
  KEY `ix_waybill_return_money_amount` (`return_money_amount`),
  KEY `ix_waybill_for_sign` (`for_sign`),
  KEY `is_cod` (`is_cod`),
  KEY `is_delivery` (`is_delivery`),
  KEY `in_warehouse` (`in_warehouse`),
  KEY `cod_amount` (`cod_amount`),
  KEY `parent_waybill_id` (`parent_waybill_id`),
  KEY `ix_cod_type` (`cod_type`),
  KEY `ix_cod_taken` (`cod_taken`),
  KEY `ix_cod_take_user` (`cod_take_user`),
  KEY `ix_given_money_user` (`given_money_user`),
  KEY `ix_waybill_cod_percent` (`cod_percent`),
  KEY `ix_waybill_is_paid` (`is_paid`),
  KEY `ix_current_employee_id` (`current_employee_id`),
  KEY `idx-waybill-is_inmagpay` (`is_inmagpay`),
  KEY `idx-waybill-inmag_amount` (`inmag_amount`),
  KEY `idx-waybill-parcel_price` (`parcel_price`),
  KEY `ix_searchable_data` (`searchable_data`(250)),
  KEY `idx-waybill-is_contact` (`is_contract`),
  KEY `idx-waybill-contract_amount` (`contract_amount`)
) ENGINE=InnoDB AUTO_INCREMENT=1404881 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
